{
  "items": [
    {
      "name": "Polynomial.card_eq_of_natDegree_le_of_coeff_le",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ {n : ℕ} {B₁ B₂ : Fin (n + 1) → ℝ},\n  {p | p.natDegree ≤ n ∧ ∀ (i : Fin (n + 1)), B₁ i ≤ ↑(p.coeff ↑i) ∧ ↑(p.coeff ↑i) ≤ B₂ i}.ncard =\n    ∏ i, (⌊B₂ i⌋ - ⌈B₁ i⌉ + 1).toNat"
    },
    {
      "name": "Poly.isPoly",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : Poly α), IsPoly ⇑f"
    },
    {
      "name": "Polynomial.card_mahlerMeasure_le_prod",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (n : ℕ) (B : NNReal),\n  {p | p.natDegree ≤ n ∧ (Polynomial.map (Int.castRingHom ℂ) p).mahlerMeasure ≤ ↑B}.ncard ≤\n    ∏ i, (2 * ⌊↑(n.choose ↑i) * B⌋₊ + 1)"
    },
    {
      "name": "MvPolynomial.cardinalMk_le_max",
      "module_name": "Mathlib.Algebra.MvPolynomial.Cardinal",
      "kind": "theorem",
      "type": "∀ {σ R : Type u} [inst : CommSemiring R],\n  Cardinal.mk (MvPolynomial σ R) ≤ max (max (Cardinal.mk R) (Cardinal.mk σ)) Cardinal.aleph0"
    },
    {
      "name": "Poly",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "definition",
      "type": "Type u → Type (max 0 u)"
    }
  ]
}
